use diamond_types::list::ListOpLog;use std::collections::BTreeMap;
fn main(){for path in std::env::args().skip(1){let bytes=std::fs::read(&path).unwrap();let log=ListOpLog::load_from(&bytes).unwrap();let names:Vec<_>=(0..log.num_agents()).map(|id|log.get_agent_name(id).to_owned()).collect();let source=std::path::Path::new(&path).with_extension("json");let data:serde_json::Value=serde_json::from_slice(&std::fs::read(source).unwrap()).unwrap();let mut actors=BTreeMap::new();let mut transactions=vec![];for txn in data["txns"].as_array().unwrap(){let span=txn["_dtSpan"].as_array().unwrap();let start=span[0].as_u64().unwrap()as usize;let end=span[1].as_u64().unwrap()as usize;if start==end{transactions.push(serde_json::json!({"empty":true}));continue;}let version=log.cg.agent_assignment.local_to_agent_version(start);let name=log.get_agent_name(version.0).to_owned();let actor=txn["agent"].as_u64().unwrap();transactions.push(serde_json::json!({"name":name,"sequence":version.1,"events":end-start}));if let Some(old)=actors.insert(actor,name.clone()){assert_eq!(old,name,"agent mapping must be consistent");}}println!("{}",serde_json::json!({"path":path,"names":names,"json_actor_names":actors,"transactions":transactions}));}}
